// Reviewed Pool domain names; entries are keyed by original obfuscated symbols.
export const classes = {
  pq: ["Ball","Holds a ball's fixed-point position, velocity, spin, motion state and in-play flag, and serialises them."],
  hm: ["Quaternion","Four fixed-point components with normalise, multiply, axis-angle setup and rotation-matrix export."],
  dl: ["Pocket","Holds a pocket centre taken from a table segment and the list of ball indices potted into it."],
  bf: ["CushionSegment","Line segment between two table outline points with a kind code at each end, tested for ball and ray collisions."],
  al: ["PoolGameModel","Owns the balls, pockets, cushion segments, shot history and rules for one table and steps the shot logic."],
  qe: ["ShotRecord","One entry of the shot history deque with shot number, phase, player, break seed, ball-in-hand mode and the pre-shot snapshot."],
  cr: ["PotEvent","Node appended to a shot when a ball falls in a pocket, holding the ball index and pocket index."],
  sq: ["GameRules","Abstract per-variant rules object holding the model and deciding turn order, fouls and end of the game."],
  af: ["EightBallRules","Rules instance created for game type 0, the default and the one restored on a restart."],
  fj: ["NineBallRules","Rules instance for game type 1 that scans balls 1 to 9 for the lowest ball still on the table."],
  rj: ["KillerRules","Rules instance for game type 2 that keeps a per-player life counter and decrements it on a miss."],
  mc: ["FreePlayRules","Rules instance for game type 3 whose checks all return fixed permissive values."],
  vp: ["TimeTrialRules","Rules instance for game type 4 that is complete once every ball except the 8 has been potted."],
  tm: ["BallSkin","Abstract ball appearance with per-index colours, sprites and sphere meshes, one subclass per skin."],
  mf: ["ClassicBallSkin","Skin that loads the balls/CLASSIC/ball1 to ball15 images."],
  vl: ["PlasmaBallSkin","Skin that loads the grad_ball and grad_lightning gradients and the top_bar_balls_plasma sprite."],
  jr: ["TikiBallSkin","Skin that loads balls/TIKI/tiki_ball_white, tiki_ball_1 and tiki_ball_black."],
  to: ["PolarBallSkin","Skin that loads balls/POLAR/polar_ball_white, polar_ball_1 and polar_ball_black."],
  lm: ["SpaceBallSkin","Skin that loads balls/SPACE/space_ball_white, space_ball_01 and space_ball_black."],
  ac: ["KillerBallSkin","Skin that loads balls/ball_killer_red and ball_killer_black."],
  ul: ["HalloweenBallSkin","Skin that loads balls/TIKI/tiki_ball_halloween and tiki_ball_halloween_lit."],
  oo: ["TableScene","Abstract table scene holding lighting, balls, meshes and sound state, specialised per table theme."],
  vc: ["ModelTableScene","Abstract table scene built from 3D model parts, parent of the tiki, space, modern and polar tables."],
  cj: ["TikiTableScene","Table scene that loads the tiki-sky.jpg backdrop and the tiki_table models."],
  gh: ["SpaceTableScene","Table scene that loads the space_ball sounds, nebula.jpg backdrop and space_table models."],
  ni: ["ModernTableScene","Table scene that loads the pool_modern music, modern-sky.jpg and new_classic_table models."],
  vf: ["PolarTableScene","Table scene that loads the polar_table/ice_isle models."],
  fk: ["PlasmaTableScene","Table scene that loads the plasma_* sounds and the pool_plasma music directly under TableScene."],
  ep: ["NetworkGameClient","GameApplet subclass reading gameport, servernum, gamecrc, member and the js5 error parameters."],
  nk: ["TranslatedUiText","Static holder of the English UI strings with a loader that overrides them from translated text keys."],
  qk: ["PoolUiText","Loader that assigns this game's text keys such as text_game_name and achievement_names to static strings."],
};
